set search_path = public, extensions;
set local lock_timeout = '5s';

alter policy reports_resident_read on public.reports using (((deleted_at IS NULL) AND ((resident_id = ( SELECT auth.uid() AS uid)) OR (( SELECT public.is_full_viewer() AS is_full_viewer) OR ((( SELECT public.admin_tier() AS admin_tier) = ANY (ARRAY['committee'::text, 'moderator'::text])) AND public.admin_sees_case(id, category, handler_id))) OR (EXISTS ( SELECT 1
   FROM public.dispatches d
  WHERE ((d.report_id = reports.id) AND (d.tanod_id = ( SELECT auth.uid() AS uid))))))));
alter policy case_handler_log_read on public.case_handler_log using ((( SELECT public.is_full_viewer() AS is_full_viewer) OR ((( SELECT public.admin_tier() AS admin_tier) = ANY (ARRAY['committee'::text, 'moderator'::text])) AND public.admin_sees_report(report_id))));
alter policy case_forwards_read on public.case_forwards using ((( SELECT public.is_full_viewer() AS is_full_viewer) OR (( SELECT public.admin_scoped() AS admin_scoped) AND public.admin_sees_report(report_id)) OR ((( SELECT public.admin_tier() AS admin_tier) = 'committee'::text) AND (from_committee = ( SELECT u.committee
   FROM public.users u
  WHERE (u.id = ( SELECT auth.uid() AS uid)))))));
alter policy detail_requests_read on public.detail_requests using (((EXISTS ( SELECT 1
   FROM public.reports r
  WHERE ((r.id = detail_requests.report_id) AND (r.resident_id = ( SELECT auth.uid() AS uid))))) OR (EXISTS ( SELECT 1
   FROM public.dispatches d
  WHERE ((d.report_id = detail_requests.report_id) AND (d.tanod_id = ( SELECT auth.uid() AS uid))))) OR (( SELECT public.is_full_viewer() AS is_full_viewer) OR ((( SELECT public.admin_tier() AS admin_tier) = ANY (ARRAY['committee'::text, 'moderator'::text])) AND public.admin_sees_report(report_id)))));
alter policy dispatch_media_read on public.dispatch_media using ((EXISTS ( SELECT 1
   FROM (public.dispatches d
     JOIN public.reports r ON ((r.id = d.report_id)))
  WHERE ((d.id = dispatch_media.dispatch_id) AND ((d.tanod_id = ( SELECT auth.uid() AS uid)) OR (( SELECT public.is_full_viewer() AS is_full_viewer) OR ((( SELECT public.admin_tier() AS admin_tier) = ANY (ARRAY['committee'::text, 'moderator'::text])) AND public.admin_sees_dispatch(dispatch_media.dispatch_id))) OR ((r.resident_id = ( SELECT auth.uid() AS uid)) AND (r.deleted_at IS NULL) AND (dispatch_media.update_id IS NULL)))))));
