   FROM public.dispatches d
  WHERE ((d.id = dispatch_updates.dispatch_id) AND (d.tanod_id = ( SELECT auth.uid() AS uid)))))));
alter policy dispatches_read on public.dispatches using (((tanod_id = ( SELECT auth.uid() AS uid)) OR (( SELECT public.is_full_viewer() AS is_full_viewer) OR ((( SELECT public.admin_tier() AS admin_tier) = ANY (ARRAY['committee'::text, 'moderator'::text])) AND public.admin_sees_report(report_id)))));
